    def _apply_yield(
        self, value: float, norm: ztyping.LimitsType, log: bool
    ) -> float | tf.Tensor:
        if self.is_extended and not norm.limits_are_false:
            if log:
                value += znp.log(self.get_yield())
            else:
                value *= self.get_yield()
        return value

