        with self._convert_sort_x(x) as x:
            value = self._single_hook_pdf(x=x, norm=norm)
            if run.numeric_checks:
                z.check_numerics(
                    value, message="Check if pdf output contains any NaNs of Infs"
                )
            return znp.asarray(z.to_real(value))

