    def _norm_pdf(self, x, norm):
        return self._call_pdf(x=x, norm=norm)

    def _call_pdf(self, x, norm):
        with suppress(FunctionNotImplemented):
            return self._pdf(x, norm)
        with suppress(FunctionNotImplemented):
            return znp.exp(self._log_pdf(x, norm))
